72#YW:/**
73#JR: * Fetch a 3D model OBJ text for a given LCSC part number.
74#SQ: * Pipeline: LCSC ID → EasyEDA component API → extract 3D UUID → fetch OBJ.
75#RK: * Returns null if no 3D model is available or on any error — never throws.
76#XJ: */
77#YW:export async function fetch3DModel(lcscId: number): Promise<string | null> {
78#JQ:  try {
79#HY:    // Step 1: Fetch component data from EasyEDA
80#KR:    const lcscStr = `C${lcscId}`;
81#BW:    const componentUrl =
82#HX:      `${EASYEDA_API_BASE}/api/products/${lcscStr}/components?version=6.4.19.5`;
83#VH:    const compResponse = await fetch(componentUrl);
84#WR:
85#BB:    if (!compResponse.ok) {
86#XJ:      console.error(`[JLCPCB] 3D fetch error: HTTP ${compResponse.status} for ${lcscStr}`);
87#BX:      return null;
88#KJ:    }
89#WY:
90#VS:    const compData = await compResponse.json();
91#RT:
92#YQ:    // Step 2: Extract 3D model UUID from shape array
93#RX:    const uuid = extract3DModelUUID(compData);
94#SZ:    if (!uuid) {
95#XR:      return null; // No 3D model available for this component
96#BZ:    }
97#ZT:
98#MV:    // Step 3: Fetch OBJ text
99#XQ:    const objUrl = `${EASYEDA_MODULES_BASE}/3dmodel/${uuid}`;
100#XP:    const objResponse = await fetch(objUrl);
101#ZS:
102#TN:    if (!objResponse.ok) {
103#JV:      console.error(`[JLCPCB] 3D fetch error: HTTP ${objResponse.status} for OBJ ${uuid}`);
104#BX:      return null;
105#HQ:    }
106#HT:
107#JW:    return await objResponse.text();
108#QB:  } catch (error) {
109#KZ:    console.error(`[JLCPCB] 3D fetch error: ${error}`);
110#MW:    return null;
111#VV:  }
112#HR:}
