114#KX:/**
115#YT: * Parse a single search result from jlcsearch API, extracting the nested
116#JN: * `extra` JSON string into structured fields.
117#HB: */
118#WM:export function parseSearchResult(raw: any): JLCPCBComponent {
119#ZZ:  let manufacturer = '';
120#VS:  let attributes: Record<string, string> = {};
121#HM:  let datasheetUrl = '';
122#JQ:
123#TX:  if (raw.extra && typeof raw.extra === 'string') {
124#VN:    try {
125#PW:      const extra = JSON.parse(raw.extra);
126#JP:      manufacturer = extra?.manufacturer?.name ?? '';
127#VQ:      if (extra?.attributes && typeof extra.attributes === 'object') {
128#WV:        attributes = extra.attributes;
129#YZ:      }
130#NH:      datasheetUrl = extra?.datasheet?.pdf ?? '';
131#XP:    } catch {
132#WR:      // Malformed extra JSON — use defaults
133#YJ:    }
134#HB:  }
135#QX:
136#ZV:  return {
137#TY:    lcsc: typeof raw.lcsc === 'number' ? raw.lcsc : 0,
138#JT:    mfr: raw.mfr ?? '',
139#RT:    package: raw.package ?? '',
140#QR:    isBasic: raw.is_basic ?? false,
141#RM:    stock: typeof raw.stock === 'number' ? raw.stock : 0,
142#BR:    price: typeof raw.price === 'number' ? raw.price : 0,
143#HH:    manufacturer,
144#NN:    attributes,
145#PR:    datasheetUrl,
146#ZR:  };
147#MQ:}
