149#TX:/**
150#BP: * Extract the 3D model UUID from EasyEDA component API response.
151#WN: * Searches the shape array in packageDetail.dataStr for an outline3D entry.
152#BJ: * Returns null if no 3D model is present.
153#MW: */
154#PY:export function extract3DModelUUID(compData: any): string | null {
155#JQ:  try {
156#WJ:    // EasyEDA v6 response structure
157#VJ:    const result = compData?.result;
158#RV:    if (!result) return null;
159#XK:
160#YT:    // Could be a single result or array of results
161#RQ:    const items = Array.isArray(result) ? result : [result];
162#VQ:
163#BB:    for (const item of items) {
164#PT:      const shapes = item?.packageDetail?.dataStr?.shape;
165#WT:      if (!Array.isArray(shapes)) continue;
166#QB:
167#PB:      for (const shape of shapes) {
168#JS:        if (typeof shape !== 'string') continue;
169#PN:
170#ZP:        // Shape entries are like "SVGNODE~{...}" — look for outline3D with uuid
171#XN:        if (shape.includes('outline3D') || shape.includes('3D')) {
172#QT:          const uuidMatch = shape.match(/"uuid"\s*:\s*"([a-f0-9]{32})"/i);
173#XT:          if (uuidMatch) {
174#VX:            return uuidMatch[1];
175#VB:          }
176#BV:        }
177#SS:      }
178#ZW:    }
179#JZ:
180#MW:    return null;
181#PZ:  } catch {
182#MW:    return null;
183#WN:  }
184#MZ:}
